// src/components/VotingPage.js
import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        setModalMessage("Failed to load candidates.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  const handleVote = (candidateId) => {
    if (submitting) return;
    setSelectedCandidate(candidateId);
    setModalType("confirm");
    setModalMessage("Confirm your vote?");
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: [selectedCandidate] },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      setModalType("success");
      setModalMessage("Vote submitted successfully.");
    } catch (error) {
      setModalType("error");
      setModalMessage("Vote failed or already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  if (loading) return <div style={styles.center}>Loading...</div>;
  if (candidates.length === 0)
    return <div style={styles.center}>No candidates available.</div>;

  return (
    <div style={styles.page}>
      <h1 style={styles.title}>Student Election 2026</h1>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={styles.section}>
          <h3 style={styles.position}>{position}</h3>

          <div style={styles.grid}>
            {list.map((candidate) => (
              <div key={candidate._id} style={styles.card}>
                {candidate.image && (
                  <img
                    src={`${API_URL}/uploads/${candidate.image}`}
                    alt=""
                    style={styles.image}
                  />
                )}

                <div style={styles.name}>
                  {candidate.firstName} {candidate.lastName}
                </div>

                <div style={styles.meta}>
                  {candidate.yearLevel} • {candidate.block}
                </div>

                <button
                  onClick={() => handleVote(candidate._id)}
                  disabled={submitting}
                  style={styles.voteButton}
                >
                  Vote
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}

      {showModal && (
        <div style={styles.overlay}>
          <div style={styles.modal}>
            <p style={{ marginBottom: 15 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={styles.modalButtons}>
                <button
                  style={styles.cancelBtn}
                  onClick={() => setShowModal(false)}
                >
                  Cancel
                </button>

                <button
                  style={styles.confirmBtn}
                  onClick={confirmVote}
                  disabled={submitting}
                >
                  {submitting ? "Submitting..." : "Confirm"}
                </button>
              </div>
            ) : (
              <button
                style={styles.confirmBtn}
                onClick={() => setShowModal(false)}
              >
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: {
    padding: 30,
    maxWidth: 1000,
    margin: "auto",
    fontFamily: "Segoe UI, sans-serif",
  },
  title: {
    textAlign: "center",
    marginBottom: 30,
    fontSize: 24,
  },
  section: {
    marginBottom: 40,
  },
  position: {
    marginBottom: 15,
    fontSize: 18,
    color: "#333",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
    gap: 15,
  },
  card: {
    background: "#fff",
    borderRadius: 10,
    padding: 15,
    textAlign: "center",
    boxShadow: "0 5px 12px rgba(0,0,0,0.05)",
  },
  image: {
    width: "100%",
    height: 140,
    objectFit: "cover",
    borderRadius: 8,
    marginBottom: 10,
  },
  name: {
    fontWeight: 600,
    fontSize: 14,
  },
  meta: {
    fontSize: 12,
    color: "#666",
    marginBottom: 10,
  },
  voteButton: {
    width: "100%",
    padding: 8,
    borderRadius: 6,
    border: "none",
    backgroundColor: "#4f46e5",
    color: "#fff",
    fontSize: 13,
    cursor: "pointer",
  },
  center: {
    padding: 40,
    textAlign: "center",
  },
  overlay: {
    position: "fixed",
    inset: 0,
    backgroundColor: "rgba(0,0,0,0.4)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    background: "#fff",
    padding: 20,
    borderRadius: 10,
    width: 300,
    textAlign: "center",
  },
  modalButtons: {
    display: "flex",
    justifyContent: "space-between",
  },
  cancelBtn: {
    padding: "6px 12px",
    border: "none",
    borderRadius: 6,
    background: "#ccc",
  },
  confirmBtn: {
    padding: "6px 12px",
    border: "none",
    borderRadius: 6,
    background: "#4f46e5",
    color: "#fff",
  },
};

export default VotingPage;
